<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { getProjectTasks, type ProjectTask } from '../api/taskApi'
const props = defineProps<{ projectId: string; projectName: string }>(); const emit = defineEmits<{ back: []; task: [task: ProjectTask] }>(); const tasks = ref<ProjectTask[]>([]); const loading = ref(true); const error = ref<string | null>(null)
async function load() { try { tasks.value = await getProjectTasks(props.projectId) } catch (e) { error.value = e instanceof Error ? e.message : 'Kunne ikke hente oppgaver.' } finally { loading.value = false } }; onMounted(load)
</script>
<template><main class="tasks-page"><header class="tasks-header"><button class="back-link" type="button" @click="emit('back')">← Tilbake til prosjekt</button><p class="eyebrow">{{ projectName }}</p><h1>Oppgaver</h1><p class="muted">Velg en oppgave for å starte arbeid og følge historikken.</p></header><p v-if="loading" class="muted">Laster oppgaver…</p><p v-if="error" class="error-text">{{ error }}</p><div v-else-if="tasks.length" class="task-list"><button v-for="task in tasks" :key="task.id" class="task-card" type="button" @click="emit('task', task)"><span class="status-pill">{{ task.status }}</span><span class="priority">{{ task.priority }}</span><h2>{{ task.title }}</h2><p v-if="task.description" class="muted">{{ task.description }}</p><small>{{ task.featureTitle || 'Ingen feature' }}</small></button></div><div v-else-if="!loading" class="empty-state"><h2>Ingen oppgaver ennå</h2><p class="muted">Godkjenn AI-oppgaver eller opprett en feature for å komme i gang.</p></div></main></template>
<style scoped>.tasks-page{min-height:100vh;padding:48px clamp(20px,6vw,88px);color:#f5f7fb;background:#0b1020}.tasks-header,.task-list,.empty-state{max-width:1100px;margin:0 auto}.back-link{display:block;margin-bottom:30px;padding:0;border:0;color:#b7f36b;background:transparent}.eyebrow{color:#b7f36b;font-size:.75rem;font-weight:700;letter-spacing:.16em}h1{font:600 clamp(2rem,4vw,3.4rem)/1 'Space Grotesk',sans-serif}.muted{color:#9da9c3}.task-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:30px}.task-card{padding:22px;border:1px solid #25304a;border-radius:16px;color:#f5f7fb;text-align:left;background:#121a30;cursor:pointer}.task-card:hover{border-color:#b7f36b}.status-pill{color:#b7f36b;font-size:.75rem;font-weight:700}.priority{float:right;color:#ffcf8a;font-size:.75rem}.task-card h2{margin:14px 0 8px}.task-card small{color:#91a2c4}.empty-state{margin-top:30px;padding:60px 20px;border:1px dashed #34415f;text-align:center}.error-text{color:#ffb8c2}</style>
